let stagedTeacherVideo=null;let stagedTeacherVideoUrl='';let offlineVideoDbPromise=null;
function clearStagedTeacherVideo(){if(stagedTeacherVideoUrl)URL.revokeObjectURL(stagedTeacherVideoUrl);stagedTeacherVideo=null;stagedTeacherVideoUrl=''}
function offlineVideoDb(){if(!('indexedDB' in window))return Promise.reject(new Error('Este dispositivo no permite guardar videos sin conexión.'));if(!offlineVideoDbPromise)offlineVideoDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('aulaya-offline-videos-v1',1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('videos'))request.result.createObjectStore('videos',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return offlineVideoDbPromise}
async function storeOfflineVideo(id,blob){const db=await offlineVideoDb();return new Promise((resolve,reject)=>{const tx=db.transaction('videos','readwrite');tx.objectStore('videos').put({id,blob,savedAt:Date.now()});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function readOfflineVideo(id){const db=await offlineVideoDb();return new Promise((resolve,reject)=>{const request=db.transaction('videos').objectStore('videos').get(id);request.onsuccess=()=>resolve(request.result?.blob||null);request.onerror=()=>reject(request.error)})}
async function removeOfflineVideo(id){const db=await offlineVideoDb();return new Promise((resolve,reject)=>{const tx=db.transaction('videos','readwrite');tx.objectStore('videos').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
state.authMode??='create';state.authMessage??='';state.schoolSelected??=null;state.schoolResults??=[];state.schoolLoading??=false;state.schoolDepartments??=[];state.schoolDepartment??='';state.schoolMunicipalities??=[];state.schoolMunicipality??='';state.schoolAreas??=[];state.schoolArea??='';
state.authIntroSeen??=false;state.authRole??='';if(!state.authEmail)state.page='auth-start';state.schoolDepartments=['Amazonas','Antioquia','Arauca','Atlántico','Bogotá, D.C.','Bolívar','Boyacá','Caldas','Caquetá','Casanare','Cauca','Cesar','Chocó','Córdoba','Cundinamarca','Guainía','Guaviare','Huila','La Guajira','Magdalena','Meta','Nariño','Norte de Santander','Putumayo','Quindío','Risaralda','San Andrés, Providencia y Santa Catalina','Santander','Sucre','Tolima','Valle del Cauca','Vaupés','Vichada'];state.schoolDepartmentsLoaded=true;
