if(!state.downloadsEmptiedForNow){state.downloads=[];state.pending=[];if(state.profileData)Object.values(state.profileData).forEach(data=>{if(data){data.downloads=[];data.pending=[]}});state.downloadsEmptiedForNow=true}
state.downloads??=[];state.pending??=[];state.streak??=0;state.lessonCompletions??=[];state.inProgressActivities??=[];
state.teacherClasses??=[];state.teacherActivities??=[];state.teacherAvatar??=0;
