if(new URLSearchParams(location.search).get('preview')==='docente'){Object.assign(state,{previewMode:true,page:'teacher-blank',teacherView:new URLSearchParams(location.search).get('vista')==='perfil'?'profile':'home',authRole:'teacher',profile:'María',firstName:'María',lastName:'',teacherCourses:['Primero','Segundo','Tercero','Cuarto','Quinto'],teacherSubjects:['Matemáticas','Lengua','Ciencias','Ciencias Sociales'],variedSubjects:false,school:{name:'Tu institución educativa'},teacherClasses:[],teacherAvatar:0})}

function profileSnapshot(){return {coins:state.coins,streak:state.streak,lessonCompletions:state.lessonCompletions,downloads:state.downloads,pending:state.pending,owned:state.owned,equipped:state.equipped,completedActivities:state.completedActivities,inProgressActivities:state.inProgressActivities,quizDone:state.quizDone,theme:state.theme,color:state.color,subject:state.subject,background:state.background||state.equipped?.Fondo}}
const GRADE_ICON_FILES={Primero:'assets/grado-1.png',Segundo:'assets/grado-2.png',Tercero:'assets/grado-3.png',Cuarto:'assets/grado-4.png',Quinto:'assets/grado-5.png'};
function teacherClassIcon(item,colorClass=''){const grade=String(item?.grade||'').trim(),src=GRADE_ICON_FILES[grade];return src?`<span class="teacher-class-icon grade-icon ${colorClass}"><img src="${src}" alt="${escapeHtml(grade)}"></span>`:`<span class="teacher-class-icon ${colorClass}">▣</span>`}
async function deleteTeacherClass(classId){const item=(state.teacherClasses||[]).find(entry=>entry.id===classId);if(!item){state.modal=null;render();return}const button=document.querySelector('[data-teacher-action="confirm-delete-class"]');const cloud=window.aulayaDb?.isConfigured()&&window.aulayaDb.userId();if(cloud&&!navigator.onLine){toastMsg('Necesitas internet para eliminar la clase.');return}if(button){button.disabled=true;button.textContent='Eliminando…'}try{if(cloud)await window.aulayaDb.deleteTeacherClass(classId);state.teacherClasses=(state.teacherClasses||[]).filter(entry=>entry.id!==classId);if(state.teacherClassId===classId)state.teacherClassId=null;state.modal=null;state.teacherView='classes';saveState();if(cloud)await window.aulayaDb.saveProfile(cloudProfilePayload()).catch(()=>{});render();toastMsg(`${item.grade} ${item.sectionLabel} se eliminó.`)}catch(error){if(button){button.disabled=false;button.textContent='Eliminar clase'}toastMsg(error.message||'No se pudo eliminar la clase. Inténtalo de nuevo.')}}
function hasUnreadNotifications(){return (state.notifications||[]).some(item=>!item.read)}
function addWelcomeNotification(role){state.notifications??=[];if(state.notifications.some(item=>item.id==='welcome'))return;const teacher=role==='teacher';state.notifications.unshift({id:'welcome',title:teacher?'¡Te damos la bienvenida, profe!':'¡Bienvenida a Aula ya!',message:teacher?'¡Hola! Teo y todo el equipo de Aula ya! te dan la bienvenida. Aquí podrás organizar tus clases y acompañar el aprendizaje de tus estudiantes.':'¡Hola! Teo y todo el equipo de Aula ya! te dan la bienvenida. Prepárate para aprender y divertirte.',createdAt:new Date().toISOString(),read:false});state.noticeRead=false}
function queueLowProgressAlert(item){if(state.authRole!=='student'||!window.aulayaDb?.isConfigured()||!item)return;const progress=Math.round(Number(item.progress)||0);if(progress<0||progress>60)return;state.pendingSupportAlerts??=[];state.supportAlertedLessons??=[];const key=`${item.subject}:${item.topic}`;if(state.supportAlertedLessons.includes(key))return;state.supportAlertedLessons.push(key);state.pendingSupportAlerts.push({key,lessonKey:key,lessonName:item.topic||item.name||'Lección',subjectName:item.subject||'',progress});saveState();flushSupportAlerts()}
async function flushSupportAlerts(){if(!navigator.onLine||!window.aulayaDb?.isConfigured()||state.authRole!=='student')return;const pending=[...(state.pendingSupportAlerts||[])];for(const alert of pending){try{await window.aulayaDb.reportLowLessonProgress(alert.lessonKey,alert.lessonName,alert.subjectName,alert.progress);state.pendingSupportAlerts=(state.pendingSupportAlerts||[]).filter(item=>item.key!==alert.key);saveState()}catch(error){console.warn('El aviso de apoyo quedó pendiente para sincronizar:',error);break}}}
async function refreshTeacherNotifications(){if(!window.aulayaDb?.isConfigured())return;try{const rows=await window.aulayaDb.loadTeacherNotifications(),welcome=(state.notifications||[]).filter(item=>item.id==='welcome'),before=JSON.stringify((state.notifications||[]).map(item=>[item.id,item.read])),next=[...welcome,...(rows||[]).map(row=>({id:row.id,source:'progress',title:`${row.student_name} necesita apoyo`,message:`${row.student_name} dejó la lección «${row.lesson_name}» de ${row.subject_name||'su materia'} con ${row.progress}% de progreso.`,createdAt:row.created_at,read:!!row.read_at}))];state.notifications=next;state.noticeRead=!next.some(item=>!item.read);if(before!==JSON.stringify(next.map(item=>[item.id,item.read])))render()}catch(error){console.warn('No se pudieron cargar las notificaciones del docente:',error)}}
let cloudSaveTimer=null;
const CLOUD_OUTBOX_KEY='aulaya-cloud-outbox-v1';
function cloudProfilePayload(){const {modal,aiMessages,sharedClassMaterials,offlineVideos,...appState}=state;return{id:window.aulayaDb?.userId(),email:state.email||state.authEmail||'',name:state.profile||'',first_name:state.firstName||'',last_name:state.lastName||'',role:state.authRole||'student',institution:state.school||{},grade:state.grade||null,courses:state.teacherCourses||[],subjects:state.teacherSubjects||[],varied_subjects:!!state.variedSubjects,app_state:appState}}
function queueCloudSave(){const userId=window.aulayaDb?.userId();if(!window.aulayaDb?.isConfigured()||!userId)return;try{const queue=JSON.parse(localStorage.getItem(CLOUD_OUTBOX_KEY)||'{}');queue[userId]={revision:Date.now(),profile:cloudProfilePayload()};localStorage.setItem(CLOUD_OUTBOX_KEY,JSON.stringify(queue))}catch(error){console.warn('No se pudo guardar la cola de sincronización:',error)}clearTimeout(cloudSaveTimer);if(navigator.onLine)cloudSaveTimer=setTimeout(flushCloudOutbox,500)}
async function flushCloudOutbox(){const userId=window.aulayaDb?.userId();if(!navigator.onLine||!window.aulayaDb?.isConfigured()||!userId)return;let queue;try{queue=JSON.parse(localStorage.getItem(CLOUD_OUTBOX_KEY)||'{}')}catch(_){queue={}}const queued=queue[userId];if(!queued?.profile)return;try{await window.aulayaDb.saveProfile(queued.profile);const latest=JSON.parse(localStorage.getItem(CLOUD_OUTBOX_KEY)||'{}');if(latest[userId]?.revision===queued.revision){delete latest[userId];if(Object.keys(latest).length)localStorage.setItem(CLOUD_OUTBOX_KEY,JSON.stringify(latest));else localStorage.removeItem(CLOUD_OUTBOX_KEY)}}catch(error){console.warn('Se conserva el progreso pendiente para volver a sincronizar:',error)}}
function saveState(){if(state.previewMode)return;try{state.profileData??={};state.profileData[state.profile]=profileSnapshot();const copy={...state};delete copy.modal;delete copy.aiMessages;delete copy.sharedClassMaterials;localStorage.setItem('aulaya-student-state',JSON.stringify(copy));const account=authAccounts.find(item=>item.email===state.authEmail);if(account){account.appState=copy;account.teacherClasses=copy.teacherClasses||account.teacherClasses||[];localStorage.setItem('aulaya-auth-accounts',JSON.stringify(authAccounts))}queueCloudSave()}catch(_){}}
function markLessonComplete(){const key=`${state.subject}:${state.topic}`;if(!state.lessonCompletions.includes(key)){state.lessonCompletions.push(key);state.streak+=1}}
function switchProfile(name){saveState();state.profile=name;state.firstName=String(name).trim().split(/\s+/)[0];state.lastName=String(name).trim().split(/\s+/).slice(1).join(" " );const saved=state.profileData?.[name];if(saved)Object.assign(state,saved);else Object.assign(state,{coins:500,streak:0,lessonCompletions:[],downloads:[],pending:[],owned:['Tigre amable'],equipped:{Avatar:'Tigre amable',Fondo:'Bosque feliz',Ropa:'Camiseta verde',Accesorios:'Gorra verde','Tema de color':'Verde'},completedActivities:[],inProgressActivities:[],quizDone:{},theme:'Verde',color:'#fbfcf6'});state.streak??=0;state.lessonCompletions??=[];state.inProgressActivities??=[];state.background=state.background||state.equipped?.Fondo||'Bosque feliz';state.page='home';render();toastMsg(`Cambiaste al perfil ${name}`)}
