function lessonVideoMarkup(){const video=lessonVideos[state.grade||'Primero']?.[state.subject];if(!video)return '';const match=video.url.match(/[?&]v=([^&]+)/),creator=video.creator||'Autoría indicada por el canal de origen';return `<section class="lesson-video-card"><h2>Video explicativo</h2><p>${escapeHtml(video.title)}</p>${match?`<div class="lesson-video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(match[1])}" title="${escapeHtml(video.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>`:`<div class="lesson-video-search"><span>▶</span><b>${video.external?'Video alojado en Mediateca EducaMadrid':'Elige un video educativo para esta lección'}</b><a href="${video.url}" target="_blank" rel="noopener noreferrer">${video.external?'Abrir video':'Ver opciones en YouTube'} ↗</a></div>`}<div class="video-attribution"><b>Créditos y derechos</b><span>Autor/canal: ${escapeHtml(creator)}${video.creator?'':' (verifica el creador al abrir el video)'}</span><small>El video y sus derechos pertenecen a su autor o canal. Aula Ya enlaza el contenido como recurso educativo.</small><a href="${video.url}" target="_blank" rel="noopener noreferrer">Abrir fuente original ↗</a></div></section>`}
function teacherActivityTopics(classId=''){const classItem=(state.teacherClasses||[]).find(item=>item.id===classId),grades=classItem?[classItem.grade]:teacherClassOptions(),registered=state.variedSubjects?['Ciencias','Matemáticas','Lengua','Inglés','Ciencias Sociales']:(state.teacherSubjects||[]),classSubjects=classItem?.subjects?.length?classItem.subjects:registered,subjects=registered.filter(subject=>classSubjects.includes(subject));return grades.flatMap(grade=>subjects.flatMap(subject=>lessonCatalog[grade]?.[subject]?[{grade,subject,topic:lessonCatalog[grade][subject]}]:[]))}
function teacherClasses(){const classes=state.teacherClasses||[],classCards=classes.map((item,index)=>`<button class="teacher-class-card" data-teacher-action="open-class" data-class-id="${escapeHtml(item.id)}">${teacherClassIcon(item,`color-${index%5}`)}<span class="teacher-class-copy"><b>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</b><small>${(item.subjects||[]).length?item.subjects.map(escapeHtml).join(' · '):'Materias por organizar'}</small><small>${(item.students||[]).length} ${(item.students||[]).length===1?'estudiante':'estudiantes'}</small></span><span class="teacher-card-arrow">›</span></button>`).join('');app.innerHTML=`${teacherHeader('home')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>Mis clases</h1><p>Organiza tus grados, secciones y estudiantes.</p></div><span class="teacher-count-pill">${classes.length} ${classes.length===1?'clase':'clases'}</span></div><button class="teacher-create-class" data-teacher-action="add-class">＋ &nbsp; Crear clase</button>${classes.length?`<section class="teacher-class-list">${classCards}</section>`:`<section class="teacher-empty-classes"><span>📚</span><h2>Aún no tienes clases disponibles</h2><p>Crea tu primera clase. Podrás indicar el grado, la sección y agregar estudiantes.</p><button class="wide-button" data-teacher-action="add-class">＋ Crear mi primera clase</button></section>`}</main>${teacherNav('classes')}`}
