function teacherClassDetail(){const item=(state.teacherClasses||[]).find(entry=>entry.id===state.teacherClassId);if(!item){state.teacherView='classes';teacherClasses();return}const students=item.students||[],activities=item.activities||[],rows=students.map((student,index)=>`<div class="teacher-student-row"><span class="teacher-student-avatar color-${index%5}">${escapeHtml(student.name.trim().slice(0,1).toUpperCase())}</span><div><b>${escapeHtml(student.name)}</b><small>Estudiante</small></div></div>`).join(''),activityRows=activities.map(activity=>`<div class="teacher-activity-row"><span>✦</span><div><b>${escapeHtml(activity.title)}</b><small>${escapeHtml([activity.grade,activity.subject==='Lengua'?'Lenguaje':activity.subject==='Ciencias Sociales'?'Sociales':activity.subject,activity.topic].filter(Boolean).join(' · ')||activity.description||'Actividad de clase')}</small></div></div>`).join('');app.innerHTML=`${teacherHeader('classes')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>${escapeHtml(item.grade)} ${escapeHtml(item.sectionLabel)}</h1><p>${item.sectionType==='letter'?'Sección':'Grupo'} ${escapeHtml(item.sectionLabel)} · ${escapeHtml(item.grade)}</p></div></div><section class="teacher-class-overview">${teacherClassIcon(item,'color-2')}<div><b>${students.length} ${students.length===1?'estudiante':'estudiantes'}</b><small>${(item.subjects||[]).length?item.subjects.map(escapeHtml).join(' · '):'Materias por organizar'}</small></div></section><button class="teacher-create-class" data-teacher-action="add-student" data-class-id="${escapeHtml(item.id)}">＋ &nbsp; Agregar estudiante</button><div class="teacher-section-title"><h2>Estudiantes</h2><span class="teacher-count-pill">${students.length}</span></div>${students.length?`<section class="teacher-student-list">${rows}</section>`:`<section class="teacher-empty-classes teacher-empty-students"><h2>Aún no hay estudiantes</h2><p>Agrega estudiantes para organizar el grupo y seguir su aprendizaje.</p><button class="wide-button" data-teacher-action="add-student" data-class-id="${escapeHtml(item.id)}">＋ Agregar estudiante</button></section>`}<div class="teacher-section-title"><h2>Actividades</h2><button data-teacher-action="add-activity" data-class-id="${escapeHtml(item.id)}">＋ Crear</button></div>${activities.length?`<section class="teacher-activity-list">${activityRows}</section>`:`<div class="teacher-mini-empty">Todavía no hay actividades para esta clase.</div>`}<button class="teacher-delete-class" data-teacher-action="delete-class" data-class-id="${escapeHtml(item.id)}">Eliminar clase</button></main>${teacherNav('classes')}`}
function teacherStudents(){const entries=(state.teacherClasses||[]).flatMap(item=>(item.students||[]).map(student=>({...student,grade:item.grade,sectionLabel:item.sectionLabel}))),rows=entries.map((student,index)=>`<div class="teacher-student-row"><span class="teacher-student-avatar color-${index%5}">${escapeHtml(student.name.trim().slice(0,1).toUpperCase())}</span><div><b>${escapeHtml(student.name)}</b><small>${escapeHtml(student.grade)} ${escapeHtml(student.sectionLabel)}</small></div></div>`).join('');app.innerHTML=`${teacherHeader('home')}<main class="teacher-page teacher-classes-page"><div class="teacher-screen-title"><div><h1>Estudiantes</h1><p>Alumnado de tus clases</p></div><span class="teacher-count-pill">${entries.length}</span></div>${entries.length?`<section class="teacher-student-list">${rows}</section>`:`<section class="teacher-empty-classes"><span>👥</span><h2>Aún no tienes estudiantes</h2><p>Crea una clase y agrega sus estudiantes para verlos aquí.</p><button class="wide-button" data-teacher-action="classes">Ir a mis clases</button></section>`}</main>${teacherNav()}`}
