function sharedVideoMaterialsMarkup(){const grade=state.grade||'Primero',subject=state.subject||'Matemáticas',topic=state.topic,offline=(state.offlineVideos||[]).filter(item=>item.grade===grade&&item.subject===subject&&item.topic===topic),rows=[...(state.sharedClassMaterials||[]).filter(item=>item.grade===grade&&item.subject===subject&&item.topic===topic)];for(const item of offline)if(!rows.some(row=>row.id===item.id))rows.push(item);if(!rows.length)return '<div class="teacher-mini-empty">Tu docente todavía no ha compartido un video para descargar.</div>';return rows.map(item=>{const saved=offline.some(video=>video.id===item.id),id=escapeHtml(item.id);return `<article class="shared-video-row"><div class="shared-video-copy"><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.description||'Video de la clase')} · ${saved?'Guardado en este dispositivo':'Video de tu docente'}</small></div><div class="shared-video-actions">${saved?`<button class="download-action done" data-play-offline-video="${id}">Ver sin internet ▶</button>`:`<button class="download-action" data-download-class-video="${id}">Descargar</button>`}</div><div class="shared-video-player" id="offline-player-${id}"></div></article>`}).join('')}
async function loadTopicSharedMaterials(){const grade=state.grade||'Primero',subject=state.subject||'Matemáticas',topic=state.topic;if(!navigator.onLine||!window.aulayaDb?.isConfigured())return;try{const rows=await window.aulayaDb.loadClassMaterials(grade,subject,topic);if(state.page!=='topic'||state.topic!==topic||state.subject!==subject)return;state.sharedClassMaterials=rows||[];const list=document.querySelector('#shared-video-list');if(list)list.innerHTML=sharedVideoMaterialsMarkup()}catch(error){console.warn('No se pudieron cargar los videos de la clase:',error)}}
async function downloadSharedClassVideo(id){const item=(state.sharedClassMaterials||[]).find(video=>video.id===id);if(!item){toastMsg('Este video ya no aparece en la lista. Conéctate e inténtalo de nuevo.');return}const button=document.querySelector(`[data-download-class-video="${CSS.escape(id)}"]`);if(button){button.disabled=true;button.textContent='Descargando…'}try{const blob=await window.aulayaDb.downloadClassVideo(item.file_path);await storeOfflineVideo(item.id,blob);state.offlineVideos??=[];state.offlineVideos=state.offlineVideos.filter(video=>video.id!==item.id);state.offlineVideos.push({id:item.id,title:item.title,description:item.description,grade:item.grade,subject:item.subject,topic:item.topic,mime_type:item.mime_type,file_size:item.file_size});saveState();const list=document.querySelector('#shared-video-list');if(list)list.innerHTML=sharedVideoMaterialsMarkup();toastMsg('Video guardado en este dispositivo para verlo sin internet.')}catch(error){if(button){button.disabled=false;button.textContent='Descargar'}toastMsg(error.message||'No se pudo guardar el video en este dispositivo.')}}
async function playOfflineClassVideo(id){try{const blob=await readOfflineVideo(id);if(!blob)throw new Error('No encontramos el archivo guardado en este dispositivo.');const player=document.querySelector(`#offline-player-${CSS.escape(id)}`);if(player){const url=URL.createObjectURL(blob);player.innerHTML=`<video controls playsinline preload="metadata" src="${url}"></video>`;player.scrollIntoView({behavior:'smooth',block:'center'})}}catch(error){toastMsg(error.message||'No se pudo abrir el video guardado.')}}
function topic(){const subject=state.subject||'Matemáticas';shell(`${heading(state.topic,'class')}<div class="class-card"><div class="class-head"><span class="teacher-mascot"><img src="assets/${subjectLogo()}" alt="Logo de ${subject}"></span><div class="class-title"><b>${state.topic}</b><small>${subject} · Aprende a tu ritmo</small></div></div><div class="class-actions"><button class="class-tab ${state.classTab!=='Materiales'?'active':''}" data-topic-tab="Actividades">▤ &nbsp; Actividades</button><button class="class-tab ${state.classTab==='Materiales'?'active':''}" data-topic-tab="Materiales">▣ &nbsp; Materiales</button></div></div>${lessonVideoMarkup()}<section class="shared-video-section"><h2>Videos compartidos por tu docente</h2><p>Descárgalos mientras tengas conexión para verlos después sin internet.</p><div id="shared-video-list">${sharedVideoMaterialsMarkup()}</div></section><button class="wide-button" data-activity="Evaluación del tema">Practicar este tema · 5 preguntas →</button><div class="empty-state"><img class="empty-progress-books" src="assets/librosnoprogreso.png" alt=""><b>${state.classTab==='Materiales'?'Más materiales próximamente':'No hay actividades por hacer'}</b><p>${state.classTab==='Materiales'?'El video de arriba es el recurso inicial para este tema.':'Cuando tu docente agregue actividades, aparecerán aquí.'}</p></div>`);loadTopicSharedMaterials()}
function notifications(){const readAction=`<button class="mark-all-read" data-action="read-all" ${state.noticeRead?'disabled':''}>${state.noticeRead?'Todas leídas':'Marcar todas como leídas'}</button>`,items=state.notifications||[],welcome=items.find(item=>item.id==='welcome'),isTeacher=state.authRole==='teacher';if(isTeacher){app.innerHTML=`<header class="teacher-profile-header"><button class="teacher-back" data-teacher-action="home" aria-label="Volver al inicio">‹</button><h1>Notificaciones</h1><span></span></header><main class="teacher-page teacher-profile-page"><div class="section-title"><h2>Tus avisos</h2>${readAction}</div><div class="notice-row welcome-notice"><span class="notice-icon welcome-tiger"><img src="assets/aulaya-mascot.png" alt="Teo, la mascota de Aula ya!"></span><span class="notice-copy"><b>${escapeHtml(welcome?.title||'¡Te damos la bienvenida, profe!')}</b><small>${escapeHtml(welcome?.message||'¡Hola! Teo y todo el equipo de Aula ya! te dan la bienvenida. Aquí podrás organizar tus clases y acompañar el aprendizaje de tus estudiantes.')}</small></span>${welcome&&!welcome.read?'<i class="unread-dot"></i>':''}</div></main>${teacherNav()}`;return}shell(`${heading('Notificaciones','home',readAction)}<div class="notice-row welcome-notice"><span class="notice-icon welcome-tiger"><img src="assets/aulaya-mascot.png" alt="Teo, la mascota de Aula ya!"></span><span class="notice-copy"><b>${escapeHtml(welcome?.title||'¡Bienvenida a Aula ya!')}</b><small>${escapeHtml(welcome?.message||'¡Hola! Teo y todo el equipo de Aula ya! te dan la bienvenida. Prepárate para aprender y divertirte.')}</small></span>${state.noticeRead?'':'<i class="unread-dot"></i>'}</div><div class="notice-row welcome-notice gift-notice"><span class="notice-icon gift-coin"><img src="assets/mondeaconlogo.png" alt="Moneda de Aula ya!"></span><span class="notice-copy"><b>¡500 monedas de regalo!</b><small>Te obsequiamos 500 monedas para que empieces tu aventura de aprendizaje.</small></span>${state.noticeRead?'':'<i class="unread-dot"></i>'}</div>`)}
function settings(){const entries=[['♙','Información de la cuenta','Nombre, correo y curso'],['▣','Cambiar contraseña','Actualiza la contraseña de tu cuenta'],['♧','Notificaciones',state.notificationsEnabled?'Activadas · Toca para desactivar':'Desactivadas · Toca para activar'],['◎','Idioma','Español'],['▤','Eliminar cuenta','Eliminar los datos de este dispositivo'],['⇥','Cerrar sesión','Disponible cuando agreguemos el acceso']];shell(`${heading('Configuración','profile')}${entries.map(([icon,title,sub])=>`<div class="settings-row" data-setting="${title}"><span class="settings-icon">${icon}</span><span class="settings-copy"><b>${title}</b><small>${sub}</small></span><span class="settings-arrow">›</span></div>`).join('')}`)}
function searchResults(query){let terms=['Matemáticas','Lengua','Ciencias','Inglés','Ciencias Sociales'];let filesFound=files.filter(f=>`${f.name} ${f.type}`.toLowerCase().includes(query.toLowerCase()));let subjects=terms.filter(x=>x.toLowerCase().includes(query.toLowerCase()));if(!query.trim()){subjects=terms;filesFound=files.slice(0,3)}return `${subjects.map(s=>`<div class="course-row search-result" data-open-subject="${s}"><span class="course-icon">${s==='Matemáticas'?'➗':s==='Lengua'?'📙':s==='Ciencias'?'🧪':s==='Inglés'?'🌐':'🌎'}</span><span class="course-detail"><b>${s}</b><small>Curso · Ver actividades y materiales</small></span><span>›</span></div>`).join('')}${filesFound.map(f=>`<div class="download-row search-result"><span class="file-icon ${f.kind}">${f.icon}</span><span class="file-copy"><b>${f.name}</b><small>${f.type} · ${f.size}</small></span><button class="download-action" data-download="${f.name}">${state.downloads.includes(f.name)?'Ver':'Descargar'}</button></div>`).join('')}${!subjects.length&&!filesFound.length?'<div class="empty-state"><div class="empty-icon">⌕</div><b>No encontramos resultados</b><p>Prueba con otra palabra.</p></div>':''}`}
function search(){shell(`${heading('Buscar','home')}<input class="form-input" id="search-input" placeholder="Busca cursos o materiales" value="${state.searchQuery||''}" autofocus><div id="search-results">${searchResults(state.searchQuery||'')}</div>`);setTimeout(()=>document.querySelector('#search-input')?.focus(),40)}
function activity(){let name=state.activeActivity||'Ejercicio 2',isVideo=name.toLowerCase().includes('video');shell(`${heading(name,'topic')}<div class="class-card"><div class="class-head"><span class="teacher-mascot">${isVideo?'▶':'✦'}</span><div class="class-title"><b>${name}</b><small>${isVideo?'Video de aprendizaje':'Actividad interactiva'}</small></div><span class="pill-count"><img class="coin-inline" src="assets/mondeaconlogo.png" alt="Monedas"> +10</span></div></div>${isVideo?`<div class="lesson-player"><div class="player-scene"><span>▶</span><small>${state.playing?'Reproduciendo':'Video listo para ver'}</small></div><div class="player-controls"><button class="wide-button" data-action="toggle-video">${state.playing?'Ⅱ Pausar':'▶ Reproducir'}</button><button class="wide-button secondary" data-action="complete-activity">Marcar como visto ✓</button></div></div><p class="topic-detail-intro">Mira el material a tu ritmo. Cuando termines, márcalo como visto para actualizar tu progreso.</p>`:`<div class="quiz-card"><h2 class="quiz-question">${name==='Juego del tema'?'¡Juguemos a repasar!':'Practica lo que aprendiste'}</h2><p class="topic-detail-intro">Responde las 5 preguntas. Si alguna se complica, recibirás un ejemplo y al final podrás repasarla.</p><button class="wide-button" data-action="start-quiz">${name==='Juego del tema'?'Empezar juego':'Empezar actividad'} →</button></div><div class="section-title"><h2>Tu progreso</h2><span class="pill-count">${state.completedActivities.includes(name)?'Completada':'Pendiente'}</span></div>`}`)}
function activeQuestionSet(){return window.AULAYA_QUESTION_BANK?.[state.grade||'Primero']?.[state.subject||'Matemáticas']?.[state.topic]||quizzes}
function updateQuizProgress(){const tracked=state.inProgressActivities.find(item=>`${item.subject}:${item.topic}:${item.name}`===`${state.subject}:${state.topic}:${state.activeActivity}`);if(tracked)tracked.progress=Math.round(((state.quizCorrectIds||[]).length/activeQuestionSet().length)*100)}
function finishQuizRun(){const activityKey=`${state.subject}:${state.topic}:${state.activeActivity}`;state.quizMode='done';state.quizFeedback=null;if(!state.completedActivities.includes(activityKey))state.completedActivities.push(activityKey);const tracked=state.inProgressActivities.find(item=>`${item.subject}:${item.topic}:${item.name}`===activityKey);if(tracked)tracked.progress=100;markLessonComplete()}
function advanceQuiz(){const questions=activeQuestionSet();state.quizFeedback=null;if(state.quizMode==='main'){state.quiz++;if(state.quiz>=questions.length){if((state.quizMissed||[]).length){state.quizMode='review';state.quizInitialMissedCount=state.quizMissed.length;state.quiz=0;state.quizQuestionOrder=[...state.quizMissed]}else finishQuizRun()}}else if(state.quizMode==='review'){state.quiz++;if(state.quiz>=state.quizQuestionOrder.length){if((state.quizMissed||[]).length){state.quiz=0;state.quizQuestionOrder=[...state.quizMissed]}else finishQuizRun()}}render()}
function quiz(){const questions=activeQuestionSet(),mode=state.quizMode||'main',order=mode==='review'?(state.quizQuestionOrder||[]):questions.map((_,index)=>index),total=mode==='review'?order.length:questions.length,questionIndex=order[state.quiz]??0,q=questions[questionIndex]||questions[0],feedback=state.quizFeedback,done=mode==='done',progress=done?100:Math.round(((state.quizCorrectIds||[]).length/questions.length)*100),review=mode==='review';const reminder=review&&!feedback&&state.quizHintByQuestion?.[questionIndex]?`<div class="quiz-feedback incorrect"><b>Recuerda este ejemplo</b><p>${escapeHtml(state.quizHintByQuestion[questionIndex])}</p></div>`:'';const feedbackMarkup=feedback?`<div class="quiz-feedback ${feedback.type==='wrong'?'incorrect':'correct'}"><b>${feedback.type==='wrong'?'Pista para resolverla':'¡Muy bien!'} </b><p>${escapeHtml(feedback.text)}</p></div><button class="wide-button" data-action="${feedback.type==='wrong'&&review?'retry-question':'next-question'}">${feedback.type==='wrong'&&review?'Intentar de nuevo':feedback.type==='wrong'?'Continuar':'Siguiente pregunta →'}</button>`:`<div class="quiz-feedback">Elige una respuesta. Si te equivocas, verás un ejemplo que te ayudará a pensar.</div>`;shell(`${heading(state.activeActivity||'Actividad','activity')}<div class="quiz-card"><div class="quiz-meta"><span>${done?'Actividad completada':`${review?'Repaso':'Pregunta'} ${state.quiz+1} de ${total} · ${state.topic}`}</span><span class="reward"><img class="coin-inline" src="assets/mondeaconlogo.png" alt="Monedas"> +10</span></div><div class="progress-line" style="margin-top:9px"><i style="width:${progress}%"></i></div>${done?`<div class="success-icon" style="margin-top:20px">✓</div><div class="quiz-question">¡Terminaste!</div><p class="topic-detail-intro">${state.quizInitialMissedCount?`Repasaste ${state.quizInitialMissedCount} ${state.quizInitialMissedCount===1?'pregunta':'preguntas'} que al principio fueron difíciles. ¡Tu avance quedó guardado!`:'Respondiste correctamente todas las preguntas. ¡Tu avance quedó guardado!'}</p><button class="wide-button" data-action="finish-quiz">Volver al tema →</button>`:`${review?'<p class="topic-detail-intro">Volvemos a las preguntas que necesitaban un segundo intento.</p>':''}${reminder}<div class="quiz-question">${escapeHtml(q.question)}</div><div class="quiz-options">${q.answers.map((answer,index)=>`<button class="quiz-option ${feedback?.type==='wrong'&&Number(feedback.chosen)===index?'wrong':feedback?.type==='correct'&&index===q.correct?'correct':''}" data-answer="${index}" ${feedback?'disabled':''}>${String.fromCharCode(65+index)}. &nbsp; ${escapeHtml(answer)}</button>`).join('')}</div>${feedbackMarkup}`}</div>`)}
function render(){document.documentElement.style.setProperty('--app-bg',state.color||'#fbfcf6');const scenes={'Bosque feliz':'url(assets/student-home-landscape.png)','Montañas':'linear-gradient(170deg,#84d8ef 0 38%,#869bb3 39% 60%,#455f82 61%)','Cascada':'linear-gradient(170deg,#74d5df 0 39%,#429bb0 40% 63%,#176d67 64%)','Mi escuela':'linear-gradient(170deg,#a8d7ef 0 40%,#f4cd80 41% 66%,#549965 67%)','Noche estrellada':'linear-gradient(170deg,#182b57 0 40%,#49668a 41% 67%,#233d4c 68%)','Valle verde':'linear-gradient(170deg,#9bd9e7 0 38%,#79bc73 39% 65%,#317647 66%)'};document.documentElement.style.setProperty('--scene',scenes[state.background||state.equipped?.Fondo]||scenes['Bosque feliz']);if(state.page==='auth-start')authWelcome();else if(state.page==='teacher-blank')teacherBlank();else if(state.page==='home')home();else if(state.page==='assistant')assistant();else if(state.page==='auth')authScreen();else if(state.page==='downloads')downloads();else if(state.page==='downloaded')downloadSuccess();else if(state.page==='custom')custom();else if(state.page==='profile')profile();else if(state.page==='settings')settings();else if(state.page==='notifications')notifications();else if(state.page==='class')course();else if(state.page==='topic')topic();else if(state.page==='quiz')quiz();else if(state.page==='activity')activity();else if(state.page==='search')search();saveState();if(state.modal)showModal()}
function downloadSuccess(){let name=state.successName||'Guía de ejercicios';shell(`<div class="success-card"><div class="success-icon">✓</div><h2>¡Listo!</h2><p>Material descargado</p><div class="download-row" style="text-align:left"><span class="file-icon pdf">PDF</span><span class="file-copy"><b>${name}</b><small>Listo para usar sin internet</small></span><span class="download-action done">✓</span></div><button class="wide-button" data-action="view-downloaded">▣ &nbsp; Ver ahora (sin internet)</button><button class="wide-button secondary" data-go="topic">↶ &nbsp; Volver al tema</button></div>`)}
function showModal(){let m=state.modal;let body='';if(m.type==='download-confirm')body=`<div class="modal-grabber"></div><h2>Descargar material</h2><p>¿Quieres guardar <b>${m.name}</b> en tu dispositivo? Podrás usarlo sin conexión.</p><div class="modal-actions"><button class="wide-button" data-confirm-download="${m.name}">Descargar ahora</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='downloaded')body=`<div class="modal-grabber"></div><div class="success-icon">✓</div><h2>¡Listo!</h2><p>${m.name} está disponible sin internet.</p><div class="modal-actions"><button class="wide-button" data-action="view-downloaded">Ver ahora (sin internet)</button><button class="wide-button secondary" data-action="close-modal">Volver al tema</button></div>`;
else if(m.type==='shop')body=`<div class="modal-grabber"></div><h2>${m.name}</h2><p>${m.owned?`Ya tienes ${m.name}. ¡Equípalo para personalizar tu espacio.`:`¿Quieres canjear ${m.price} monedas por ${m.name}? Tienes ${state.coins} monedas.`}</p><div class="modal-actions">${m.owned?`<button class="wide-button" data-equip="${m.name}">Usar ${m.name}</button>`:`<button class="wide-button" data-buy="${m.name}" data-price="${m.price}" ${state.coins<m.price?'disabled':''}>Canjear por <img class="coin-inline" src="assets/mondeaconlogo.png" alt="Monedas"> ${m.price}</button>`}<button class="wide-button secondary" data-action="close-modal">Ahora no</button></div>`;
else if(m.type==='remove')body=`<div class="modal-grabber"></div><h2>¿Eliminar material descargado?</h2><p>Se liberará espacio. Podrás descargarlo nuevamente cuando tengas internet.</p><div class="modal-actions"><button class="danger-button" data-confirm-remove="${m.name}">Eliminar</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='remove-profile')body=`<div class="modal-grabber"></div><h2>¿Eliminar el perfil ${m.name}?</h2><p>Se borrará su progreso guardado en este dispositivo.</p><div class="modal-actions"><button class="danger-button" data-confirm-profile-remove="${m.name}">Eliminar perfil</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='account')body=`<div class="modal-grabber"></div><h2>Información de la cuenta</h2><p>Actualiza los datos que aparecen en tu perfil.</p><input class="form-input" id="account-name" value="${state.profile}" placeholder="Nombre"><input class="form-input" id="account-email" value="${state.email||'samantha@gmail.com'}" type="email" placeholder="Correo electrónico"><div class="modal-actions"><button class="wide-button" data-action="save-account">Guardar cambios</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='password')body=`<div class="modal-grabber"></div><h2>Cambiar contraseña</h2><p>Elige una contraseña nueva de al menos 8 caracteres.</p><label>Nueva contraseña<input class="form-input" id="new-password" type="password" autocomplete="new-password" placeholder="Mínimo 8 caracteres"></label><label>Confirma la contraseña<input class="form-input" id="confirm-new-password" type="password" autocomplete="new-password" placeholder="Repite la contraseña"></label><p class="auth-message" id="auth-message" role="alert" ${state.authMessage?'':'hidden'}>${escapeHtml(state.authMessage||'')}</p><div class="modal-actions"><button class="wide-button" data-action="change-account-password">Guardar contraseña</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='delete-account')body=`<div class="modal-grabber"></div><h2>Eliminar los datos de este dispositivo</h2><p>Se borrarán los perfiles y avances guardados localmente. Esta acción no se puede deshacer.</p><div class="modal-actions"><button class="danger-button" data-action="confirm-delete-account">Eliminar datos</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='add-profile')body=`<div class="modal-grabber"></div><h2>Agregar perfil</h2><p>Crea un perfil para que cada estudiante tenga su propio avance y avatar.</p><input class="form-input" id="new-profile" placeholder="Nombre del perfil" maxlength="20"><div class="modal-actions"><button class="wide-button" data-action="save-profile">Crear perfil</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='teacher-class')body=`<div class="modal-grabber"></div><h2>Crear clase</h2><p>Elige el grado y define la sección para identificar tu grupo.</p><label class="teacher-form-label">Curso o grado<select class="form-input" id="teacher-class-grade"><option value="">Selecciona el grado</option>${(m.grades||teacherClassOptions()).map(grade=>`<option value="${escapeHtml(grade)}">${escapeHtml(grade)}</option>`).join('')}</select></label><div class="teacher-form-pair"><label class="teacher-form-label">Tipo de sección<select class="form-input" id="teacher-section-type"><option value="letter">Letra</option><option value="number">Número</option></select></label><label class="teacher-form-label">Sección<input class="form-input" id="teacher-section-value" value="A" maxlength="2" placeholder="A o 1"></label></div>${(m.subjects||[]).length?`<fieldset class="teacher-subject-picker"><legend>Materias del grupo <small>(opcional)</small></legend><div>${m.subjects.map((subject,index)=>`<label><input type="checkbox" name="teacher-class-subject" value="${escapeHtml(subject)}" ${index===0?'checked':''}> ${escapeHtml(subject)}</label>`).join('')}</div></fieldset>`:''}<div class="modal-actions"><button class="wide-button" data-action="save-teacher-class">Crear clase</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`;
else if(m.type==='teacher-delete-class'){const item=(state.teacherClasses||[]).find(entry=>entry.id===m.classId),name=item?`${item.grade} ${item.sectionLabel}`:'esta clase';body=`<div class="modal-grabber"></div><h2>¿Eliminar ${escapeHtml(name)}?</h2><p>La clase dejará de aparecer para ti y para sus estudiantes. También se borrarán sus actividades y los videos compartidos en ella. Esta acción no se puede deshacer.</p><div class="modal-actions"><button class="danger-button" data-teacher-action="confirm-delete-class">Eliminar clase</button><button class="wide-button secondary" data-action="close-modal">Cancelar</button></div>`}
else if(m.type==='teacher-student')body=`<div class="modal-grabber"></div><h2>Agregar estudiante</h2><p>Escribe el correo con el que el estudiante creó su cuenta. Verificaremos que pertenezca a tu misma institución y ubicación, y su nombre se agregará automáticamente.</p><label class="teacher-form-label">Correo del estudiante<input class="form-input" id="teacher-student-search" type="email" inputmode="email" maxlength="120" placeholder="estudiante@correo.com" autocomplete="off" autocapitalize="off" spellcheck="false"></label><div id="teacher-student-results" class="teacher-student-search-results"><div class="teacher-student-search-hint">Escribe el correo completo del estudiante.</div></div><div class="modal-actions"><button class="wide-button secondary" data-action="close-modal">Cerrar</button></div>`;
else if(m.type==='teacher-activity')body=teacherActivityModalMarkup(m);
else body=`<div class="modal-grabber"></div><h2>${m.title||'Configuración'}</h2><p>${m.description||'Esta opción estará disponible próximamente.'}</p><div class="modal-actions"><button class="wide-button secondary" data-action="close-modal">Entendido</button></div>`;
app.insertAdjacentHTML('beforeend',`<div class="modal-scrim" data-action="scrim"><div class="modal-sheet">${body}</div></div>`)}
function go(page){if(state.page==='activity'&&page!=='activity'){const leaving=state.inProgressActivities?.find(item=>`${item.subject}:${item.topic}:${item.name}`===`${state.subject}:${state.topic}:${state.activeActivity}`);queueLowProgressAlert(leaving)}state.modal=null;state.page=page;state.classTab='Actividades';if(page!=='topic')state.topic=state.topic||'Números naturales';render()}

function aiPanel(status,message='',progress=0){const panel=document.querySelector('#ai-model-panel');if(!panel)return;const installed=localStorage.getItem('teo-model-cache-v2')==='ready',ready=status==='ready';panel.hidden=ready||(installed&&status==='loading');document.querySelector('.ai-welcome')?.classList.toggle('ai-welcome-hidden',ready||(installed&&status==='loading'));document.querySelector('.ai-chat')?.classList.toggle('ai-chat-ready',ready||(installed&&status==='loading'));const button=panel.querySelector('[data-action="ai-load"]'),bar=panel.querySelector('.ai-progress'),fill=panel.querySelector('.ai-progress span'),label=panel.querySelector('.ai-model-status'),input=document.querySelector('#ai-chat-input'),send=document.querySelector('#ai-chat-form button');if(label)label.textContent=message||'Requiere un navegador compatible con WebGPU.';if(bar)bar.hidden=status!=='loading';if(fill)fill.style.width=`${Math.max(0,Math.min(100,progress))}%`;if(button){button.disabled=status==='loading';button.textContent=status==='loading'?`Preparando modelo · ${Math.round(progress)}%`:status==='ready'?'Teo listo':status==='error'?'Intentar de nuevo':'Preparar modelo'}if(input)input.disabled=status!=='ready';if(send)send.disabled=status!=='ready'}
async function prepareTeoModel(){if(!window.teoOfflineAI){aiPanel('error','No se pudo cargar el motor local. Recarga la app e inténtalo de nuevo.');return}aiPanel('loading','Preparando a Teo. La primera descarga puede tardar.',0);try{await window.teoOfflineAI.init(progress=>aiPanel('loading',progress.text||'Descargando y preparando a Teo…',progress.progress||0));aiPanel('ready','Teo está listo. El modelo quedó guardado en este dispositivo.',100);document.querySelector('#ai-chat-input')?.focus()}catch(error){localStorage.removeItem('teo-model-cache-v2');const message=!navigator.onLine?'No hay conexión y el modelo no está guardado. Conéctate una vez para descargarlo.':error?.message?.includes('WebGPU')?'Este navegador o dispositivo no admite WebGPU para ejecutar el modelo. Prueba con Chrome o Edge actualizado.':'No se pudo preparar el modelo. Revisa tu conexión, el espacio disponible y vuelve a intentarlo.';aiPanel('error',message);console.error('Teo:',error)}}
function isAcademicRequest(text){const value=String(text||'').trim().toLocaleLowerCase('es');return /\b(materia|materias|clase|clases|colegio|escuela|estudi|académ|academic|aprend|tarea|deber|material|tema|lección|leccion|actividad|texto|lectura|libro|cuaderno|ejemplo|ejercicio|práctica|practica|resumen|explica|explícame|explicame|enséñame|ensename|ayúdame|ayudame|ayuda|resuelve|resolver|calcula|calcular|operación|operacion|suma|resta|multiplic|división|division|fracción|fraccion|número|numero|gramática|gramatica|ortografía|ortografia|vocabulario|traduce|traducir|ciencia|naturaleza|historia|geografía|geografia|inglés|ingles|lengua|sociales|respuesta|duda|pregunta|concepto|definición|definicion|problema|fórmula|formula|esquema|mapa conceptual|análisis|analisis|investiga|investigación|investigacion|experimento|experimento|\d+\s*[+\-×÷=])/i.test(value)||/[¿?]/.test(value)}
function englishLike(text){const words=String(text||'').toLocaleLowerCase('en').match(/\b(the|and|you|your|is|are|what|how|this|that|because|with|for|can|i|we|let|here)\b/g)||[];return words.length>=3}
async function sendTeoMessage(question){question=String(question||'').trim();if(!question||!window.teoOfflineAI?.ready)return;state.aiMessages??=[];if(!isAcademicRequest(question)){state.aiMessages.push({role:'user',content:question},{role:'assistant',content:'Puedo ayudarte con materias, tareas, lecturas, ejemplos y ejercicios escolares. ¿Qué tema estás aprendiendo?'});renderAiMessages();const field=document.querySelector('#ai-chat-input');if(field)field.value='';field?.focus();return}state.aiMessages.push({role:'user',content:question});renderAiMessages();const input=document.querySelector('#ai-chat-input'),send=document.querySelector('#ai-chat-form button');if(input)input.value='';if(input)input.disabled=true;if(send)send.disabled=true;const system=`Eres Teo, el jaguar tutor de Aula ya! para niñas y niños de primaria en Colombia. Responde exclusivamente en español latinoamericano sencillo; nunca contestes en inglés, aunque el estudiante escriba en inglés. Usa frases cortas, palabras fáciles y tono cálido. Puedes contestar preguntas y también pedidos académicos aunque no estén escritos como pregunta: da ejemplos cuando te los pidan, explica temas, aclara dudas sobre el material, ayuda con tareas y crea ejercicios escolares. Mantén toda la conversación enfocada en el aprendizaje y en temas académicos. Si el mensaje no es académico, responde brevemente que solo puedes ayudar con materias y actividades escolares y pregunta qué tema está aprendiendo. Guía paso a paso y no solo entregues la respuesta. No solicites datos personales. Si no sabes algo, dilo con honestidad y sugiere consultar a su docente o a un adulto. Tema actual de la app: ${state.subject||'aprendizaje general'}.`;const messages=[{role:'system',content:system},...(state.aiMessages||[]).slice(-8)];try{let answer=await window.teoOfflineAI.reply(messages);if(englishLike(answer))answer=await window.teoOfflineAI.reply([{role:'system',content:'Responde solo en español latinoamericano sencillo para un niño de primaria. El pedido es académico: da la explicación o ejemplo solicitado, en español.'},{role:'user',content:`Pedido académico del estudiante: ${question}\nBorrador que debes expresar en español claro: ${answer}`}]);if(englishLike(answer))answer='Te ayudo con eso en español. ¿Puedes contarme un poco más sobre el tema de clase?';state.aiMessages.push({role:'assistant',content:answer||'No logré formular una respuesta. ¿Lo intentamos de otra manera?'});}catch(error){state.aiMessages.push({role:'assistant',content:'Ups, tuve un problema al pensar. Inténtalo otra vez en un momento.'});console.error('Teo:',error)}renderAiMessages();if(input)input.disabled=false;if(send)send.disabled=false;input?.focus()}
function renderAiMessages(){const box=document.querySelector('#ai-messages');if(box){box.innerHTML=aiMessagesMarkup();box.scrollTop=box.scrollHeight}}

