app.addEventListener('change',e=>{if(e.target.id==='teacher-activity-video'){const file=e.target.files?.[0]||null;if(file&&(!['video/mp4','video/webm'].includes(file.type)||file.size>52428800)){clearStagedTeacherVideo();e.target.value='';document.querySelector('.teacher-video-preview-wrap')?.remove();toastMsg('Elige un video MP4 o WebM de máximo 50 MB.');return}clearStagedTeacherVideo();stagedTeacherVideo=file;const label=document.querySelector('#teacher-video-file-name');if(label)label.textContent=file?`${file.name} · ${(file.size/1048576).toFixed(1)} MB`:'El estudiante podrá descargarlo para verlo sin internet.';if(file){stagedTeacherVideoUrl=URL.createObjectURL(file);e.target.closest('.teacher-form-label')?.insertAdjacentHTML('afterend',`<div class="teacher-video-preview-wrap"><b>Vista previa</b><video class="teacher-video-preview" controls playsinline preload="metadata" src="${stagedTeacherVideoUrl}"></video></div>`)}else document.querySelector('.teacher-video-preview-wrap')?.remove()}else if(e.target.id==='teacher-activity-class'){if(state.modal?.type==='teacher-activity'){state.modal.selectedClassId=e.target.value;render()}}else if(e.target.id==='teacher-section-type'){const field=document.querySelector('#teacher-section-value');if(field){field.value=e.target.value==='letter'?'A':'1';field.maxLength=e.target.value==='letter'?1:2;field.placeholder=e.target.value==='letter'?'A':'1'}}});


app.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='save-account'){const nextName=document.querySelector('#account-name')?.value.trim(),email=document.querySelector('#account-email')?.value.trim();if(!nextName||!email){toastMsg('Completa tu nombre y correo.');return}const oldName=state.profile;state.profile=nextName;state.firstName=nextName.split(/\s+/)[0];state.lastName=nextName.split(/\s+/).slice(1).join(" " );state.profiles=state.profiles.map(n=>n===oldName?nextName:n);state.email=email;const account=authAccounts.find(item=>item.email===state.authEmail);if(account){account.email=email;account.name=nextName;account.firstName=state.firstName;account.lastName=state.lastName;state.authEmail=email;localStorage.setItem('aulaya-auth-accounts',JSON.stringify(authAccounts))}state.modal=null;render();toastMsg('Datos de cuenta guardados.')}else if(action==='confirm-delete-account'){localStorage.removeItem('aulaya-student-state');location.reload()}});

app.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='ai-load')prepareTeoModel();else if(action==='ai-clear'){state.aiMessages=[];renderAiMessages()}});
app.addEventListener('submit',e=>{if(e.target.id==='ai-chat-form'){e.preventDefault();sendTeoMessage(document.querySelector('#ai-chat-input')?.value)}});

// Demo content is available offline after the initial screen.
state.offline=!navigator.onLine;
window.addEventListener('offline',()=>{state.offline=true;if(state.page==='home')render()});
window.addEventListener('online',()=>{state.offline=false;flushCloudOutbox();flushSupportAlerts();if(state.page==='home')render()});
window.addEventListener('pagehide',()=>{if(state.page==='activity'){const leaving=state.inProgressActivities?.find(item=>`${item.subject}:${item.topic}:${item.name}`===`${state.subject}:${state.topic}:${state.activeActivity}`);queueLowProgressAlert(leaving)}});
render();
if(window.aulayaDb?.isConfigured())setTimeout(()=>{flushCloudOutbox();flushSupportAlerts();if(state.authRole==='teacher')refreshTeacherNotifications()},0);
setInterval(()=>{if(state.authRole==='teacher'&&state.page==='teacher-blank')refreshTeacherNotifications()},45000);
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(error=>console.warn('Modo sin conexión no pudo activarse:',error)));
setTimeout(()=>document.querySelector('#splash')?.classList.add('gone'),700);
